{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "PET imaging in rats and nonhuman primates showed clear brain uptake of an N-methylpiperazine aryl analogue, demonstrating that this piperazine-heteroaryl scaffold crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "A fluorophenyl-piperazine analogue showed extremely high brain uptake in mice with no brain metabolites, directly supporting CNS access for a close structural relative.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Biodistribution in rats showed high and consistent brain uptake (0.28-0.35 %ID/g) for an iodophenyl-piperazine analogue, confirming robust brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "A related piperazine analogue achieved a brain-to-blood ratio greater than 20:1 in rats, indicating strong CNS exposure after systemic administration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A piperazine-fused heteroaromatic analogue had a brain/plasma ratio of 17.5 in pharmacokinetic studies, showing it easily crosses the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "PET imaging in monkeys showed rapid brain accumulation of a piperazine-containing radiotracer, supporting meaningful CNS access for this chemotype.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple highly transferable experimental analogues with the same piperazine-aryl/heteroaryl core demonstrate robust brain uptake, high brain-to-plasma ratios, and PET-visible CNS exposure. The physicochemical prior is also favorable, so the query is predicted to have meaningful CNS access.",
  "evidence_gaps": [
    "No direct experimental BBB measurement is available for the exact query molecule.",
    "Efflux transporter status (e.g., P-gp) was not directly measured for the query or most analogues.",
    "Some analogue endpoints are qualitative or based on radiolabeled tracers rather than unbound brain concentrations."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

